insert into ponew values
(1, 1, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A pillow between the legs in the lateral position mainly prevents:', '["Dislocation of the upper hip joint", "Venous air embolism from the veins of the legs", "Pressure on the knees, ankles and nerves", "Spinal cord injury in the lower back"]'::jsonb, 2, 'Bony prominences press together without padding.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 2, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A needle holder should grasp a curved needle:', '["At the swaged end of the needle only", "In the middle of the suture thread", "At the very point of the needle, for the firmest grip", "One-third to halfway from the swaged end"]'::jsonb, 3, 'Holding the point blunts it; holding the swage can break it.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 3, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Oxidised regenerated cellulose (e.g. Surgicel) is a:', '["Topical haemostatic agent", "Type of wound drain left under the skin", "Skin antiseptic solution", "Non-absorbable suture"]'::jsonb, 0, 'Others include gelatin sponges and fibrin sealants.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 4, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Pressure injuries in long surgery are best prevented by:', '["Tight straps over the hips and knees to stop any movement", "Pressure-relieving mattresses and padding", "Avoiding all positioning aids and pads", "Placing the patient directly on metal"]'::jsonb, 1, 'Check skin before and after surgery and document findings.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 5, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Before a laser is used in theatre, the nurse must ensure:', '["Correct eyewear for that laser and warning signs", "The windows are uncovered for natural light", "Reflective metal instruments are used nearby", "The alcohol skin preparation is still wet when the laser is started"]'::jsonb, 0, 'Damp swabs around the site and non-reflective instruments reduce fire and reflection risk.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 6, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'In the lateral position for kidney surgery, an axillary roll is placed:', '["Under the head as a pillow to keep the neck flexed", "Under the upper shoulder to lift it off the table", "Between the knees only, to separate the legs", "Just below the lower axilla, to protect the plexus"]'::jsonb, 3, 'It takes weight off the lower shoulder and axillary vessels.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 7, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Polypropylene (Prolene) is commonly chosen for vascular anastomosis because it is:', '["Non-absorbable, smooth and causes little reaction", "Rapidly absorbed by the body within 7 days", "Made from purified animal intestine and rapidly absorbed", "Braided, so it holds knots very easily"]'::jsonb, 0, 'Its monofilament surface passes smoothly through vessels.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 8, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A patient tells the nurse she is allergic to latex. The best plan is to:', '["Postpone surgery until the allergy settles down", "List her first in a latex-free prepared theatre", "Use latex gloves but avoid latex catheters", "Give her an antihistamine and proceed as normal"]'::jsonb, 1, 'Latex particles in the air settle overnight, so the first case is safest.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 9, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A theatre nurse is pregnant. She should be:', '["Assigned to all the X-ray cases on the list, wearing a thin apron only", "Asked to stand closest to the C-arm during X-rays", "Allowed to work only without heavy lead aprons", "Protected from radiation and gas exposure as per policy"]'::jsonb, 3, 'Report the pregnancy to occupational health to assess risks.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 10, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The patient is asked to empty the bladder before going to theatre mainly to:', '["Prevent bladder injury and incontinence", "Allow the urine to be sent for culture", "Help the patient to sleep before surgery", "Shorten the fasting time before surgery"]'::jsonb, 0, 'A catheter may be inserted for long procedures.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 11, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'During general anaesthesia the patient''s eyes are taped closed mainly to prevent:', '["Pupil dilation from the drugs", "Corneal abrasion and drying", "Retinal detachment from pressure", "The patient waking up early"]'::jsonb, 1, 'Lack of blinking and tear production leave the cornea exposed.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 12, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A nurse is about to give a second drug into the sterile field. The best way to transfer it is:', '["Ask the surgeon to take it straight from the unsterile vial", "Use a sterile transfer device, or let the scrub nurse draw it up", "Inject it through the drapes onto the instrument table", "Pour it over the edge of the vial from a great height into a bowl"]'::jsonb, 1, 'Read the label aloud and confirm with the scrub nurse.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 13, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Surgical smoke from diathermy should be removed using:', '["A fan blowing across the field", "An ordinary surgical mask worn by all staff in the theatre", "A local smoke evacuation system", "Simply opening the theatre door"]'::jsonb, 2, 'Smoke contains toxic chemicals and viable particles.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 14, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'At the end of an operation, before the patient leaves theatre, the Sign Out confirms:', '["The patient''s fasting time and last food or drink", "Patient identity and consent, checked before induction", "The allergy status, confirmed before the anaesthetic", "Procedure, counts, specimens and recovery concerns"]'::jsonb, 3, 'Sign Out is led by a team member, often the nurse.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 15, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Before blood is given in theatre, the bag must be checked against the patient''s identity by:', '["One porter when collecting the blood", "The laboratory staff only, by phone", "Two qualified staff at the bedside", "The surgeon alone, by telephone"]'::jsonb, 2, 'Check name, number, blood group, expiry and compatibility label.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 16, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'If the surgeon refuses to stop for the Time Out, the nurse should:', '["Insist on the checklist and escalate if needed", "Do it quietly alone after the incision is made", "Leave the theatre and report it the next week", "Skip it and record on the form that it was done"]'::jsonb, 0, 'Every team member has the right and duty to speak up.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 17, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'During surgery, the circulating nurse documents:', '["Times, staff, counts, implants, specimens and incidents", "Nothing until the patient is discharged home from the ward afterwards", "Only the time the surgery started and finished", "Only the surgeon''s name and grade on the form"]'::jsonb, 0, 'Records must be clear, contemporaneous and signed.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 18, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', '''Cut'' mode on an electrosurgical unit differs from ''coagulation'' mode because cut mode:', '["Only works with bipolar forceps", "Uses a high-voltage interrupted waveform for clotting", "Uses a continuous low-voltage waveform that vaporises tissue", "Uses no electrical current at all, only heat from the pencil tip"]'::jsonb, 2, 'Coagulation uses a higher-voltage intermittent waveform.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 19, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Sterile drapes, once placed, should:', '["Be shaken out well over the patient before use, then adjusted often", "Be lifted to check the skin underneath regularly", "Not be moved, as moving them spreads contamination", "Be adjusted towards the incision whenever needed"]'::jsonb, 2, 'If a drape is misplaced, discard it and apply a new one.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 20, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Immediate-use (flash) steam sterilisation should be used:', '["For all instruments at the end of each operating day", "Routinely for implants, to save time on busy lists", "Only in an emergency when no sterile item is available", "Instead of cleaning when items are heavily soiled with blood"]'::jsonb, 2, 'Implants should not be flash sterilised except in a documented emergency.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 21, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Mayo scissors are used mainly to cut:', '["Delicate blood vessels and nerves only", "Corneal tissue and fine vessels in eye surgery", "Bone and cartilage in orthopaedics", "Heavy tissue such as fascia, and sutures"]'::jsonb, 3, 'Metzenbaum scissors are finer, for delicate tissue.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 22, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A swab ticket or whiteboard count must show:', '["A total written at the end of the case from memory", "Only the needles used by the operating surgeon", "Only the items opened at the start of the case", "Every added item, recorded when it is added"]'::jsonb, 3, 'Additions must be counted when added.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 23, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'To protect staff from X-rays from an image intensifier (C-arm), the most effective simple measure is:', '["More distance from the source and a lead apron", "Standing as close as possible to the beam", "Wearing a surgical mask and eye goggles during imaging", "Turning off the room lights during imaging"]'::jsonb, 0, 'Radiation dose falls with the square of the distance.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 24, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A closed suction drain (e.g. Redivac) works by:', '["Applying negative pressure to remove fluid from the wound", "Keeping the wound edges open for packing", "Letting fluid flow out by gravity into the dressing", "Pumping antibiotic solution into the wound to prevent infection"]'::jsonb, 0, 'Note the drain type, amount and colour of drainage on the chart.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 25, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The main role of the surgical first assistant (scrub practitioner as assistant) includes:', '["Retraction, cutting sutures and clearing the field", "Leaving the field to collect any supplies", "Giving the general anaesthetic to the patient", "Signing the consent form and checking the patient on behalf of the surgeon"]'::jsonb, 0, 'Assistants work within their trained competence.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 26, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Standard surgical gowns and drapes for long or wet operations should be:', '["Paper that dissolves when it is wet", "Any material, as long as it is clean", "Thin cotton that absorbs fluid well and keeps the field dry", "Fluid-resistant (impervious) in critical zones"]'::jsonb, 3, 'Fluid resistance prevents strike-through contamination.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 27, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A blood spill on the theatre floor is first managed by:', '["Cover it with a drape until the end of the list", "Wipe it with a dry mop and then leave it to dry before the next case", "Spray air freshener over it and clean it tomorrow", "Wear PPE, absorb the spill, then disinfect with chlorine"]'::jsonb, 3, 'Large blood spills usually need 10,000 ppm available chlorine.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 28, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Which item is a correct rule for theatre attire?', '["Masks may hang around the neck between cases", "Long nails are allowed if gloves are worn", "Scrubs worn outside are fine without change", "Jewellery is removed and all hair is covered"]'::jsonb, 3, 'Rings and long or artificial nails harbour bacteria and tear gloves.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 29, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A patient is transferred from trolley to operating table. The safest method is:', '["Asking the sedated patient to climb across alone", "Using a slide sheet or board with enough staff", "Lifting the patient up under both arms", "One nurse pulling the sheet across on her own"]'::jsonb, 1, 'Brakes on, heights level and the anaesthetist controls the head.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 30, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A sterile field becomes contaminated when:', '["A sterile gown touches a sterile drape lightly", "A wet drape lets fluid soak through from below", "The scrub nurse stands facing the sterile field", "A sterile instrument touches another sterile item"]'::jsonb, 1, 'Strike-through allows bacteria to pass with the fluid.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 31, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The openings located on either side of the vaginal orifice are the:', '["Skene''s ducts", "Bartholin''s ducts", "Hymenal ducts", "Urethral meatus"]'::jsonb, 1, 'Bartholin''s (greater vestibular) gland ducts open on either side of the vaginal orifice. Skene''s ducts open beside the urethra.', 'PON 411 · Anatomy & Physiology'),
(1, 32, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The epithelial cells lining the endocervical canal are:', '["Tall and squamous", "Tall and columnar", "Flat and transitional", "Tall and cuboidal"]'::jsonb, 1, 'The endocervical canal is lined by tall, mucus-secreting columnar epithelium.', 'PON 411 · Anatomy & Physiology'),
(1, 33, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which of these is a granulocyte?', '["An eosinophil", "A lymphocyte", "A macrophage", "An erythrocyte"]'::jsonb, 0, 'Granulocytes are neutrophils, eosinophils and basophils. Lymphocytes and monocytes/macrophages are agranulocytes.', 'PON 411 · Anatomy & Physiology'),
(1, 34, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The approximate total body water content of an adult woman is:', '["70%", "80%", "60%", "50%"]'::jsonb, 3, 'Total body water is about 60% of body weight in adult men and about 50–55% in women, who have more body fat.', 'PON 411 · Anatomy & Physiology'),
(1, 35, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The pancreas functions as both an endocrine and exocrine organ; insulin is an example of its:', '["Only a digestive enzyme", "Endocrine function", "Exocrine function", "Neither function"]'::jsonb, 1, 'Insulin, secreted by the islets of Langerhans directly into the bloodstream, exemplifies the pancreas''s endocrine function, distinct from its exocrine secretion of digestive enzymes into the duodenum.', 'PON 411 · Anatomy & Physiology'),
(1, 36, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Cells of which layer of the epidermis are keratinised and dead?', '["Stratum granulosum", "Stratum basale", "Stratum spinosum", "Stratum corneum"]'::jsonb, 3, 'The stratum corneum, the outermost layer, is made of dead keratinised cells.', 'PON 411 · Anatomy & Physiology'),
(1, 37, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The brain uses about what percentage of the body''s oxygen consumption?', '["15%", "20%", "10%", "5%"]'::jsonb, 1, 'The brain is about 2% of body weight but uses about 20% of the body''s oxygen.', 'PON 411 · Anatomy & Physiology'),
(1, 38, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The nervous system can inhibit or stimulate other systems in order to maintain:', '["Mental balance", "Homeostasis", "Integration", "Growth"]'::jsonb, 1, 'By stimulating or inhibiting other systems, the nervous system helps maintain homeostasis.', 'PON 411 · Anatomy & Physiology'),
(1, 39, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Serum is blood plasma minus its:', '["Sodium ions", "Calcium ions", "Fibrinogen", "Albumin"]'::jsonb, 2, 'Serum is plasma with the clotting proteins, chiefly fibrinogen, removed.', 'PON 411 · Anatomy & Physiology'),
(1, 40, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which meningeal layer lies closest to the brain surface?', '["Periosteum", "Dura mater", "Pia mater", "Arachnoid mater"]'::jsonb, 2, 'The pia mater is the innermost, delicate meningeal layer that closely adheres to the surface of the brain and spinal cord.', 'PON 411 · Anatomy & Physiology'),
(1, 41, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The olfactory nerve is responsible for:', '["Vision", "Taste", "Smell", "Hearing"]'::jsonb, 2, 'The olfactory nerve (CN I) carries the sense of smell.', 'PON 411 · Anatomy & Physiology'),
(1, 42, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which organs are both involved in the synthesis of calcitriol and erythropoietin?', '["Thyroid and thymus", "Liver and kidneys", "Parathyroids and pancreatic islets", "Anterior and posterior pituitary"]'::jsonb, 1, 'The liver (25-hydroxylation) and kidney (1-hydroxylation) both make calcitriol. Both also produce erythropoietin, mainly the kidney.', 'PON 411 · Anatomy & Physiology'),
(1, 43, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which skin cells alert the immune system to pathogens?', '["Tactile (Merkel) cells", "Dendritic (Langerhans) cells", "Keratinocytes", "Melanocytes"]'::jsonb, 1, 'Dendritic (Langerhans) cells in the epidermis capture antigens and alert the immune system.', 'PON 411 · Anatomy & Physiology'),
(1, 44, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which female structure is homologous to the male penis?', '["Vagina", "Ovary", "Clitoris", "Urethra"]'::jsonb, 2, 'The clitoris develops from the same embryonic tissue (genital tubercle) as the penis.', 'PON 411 · Anatomy & Physiology'),
(1, 45, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The gag reflex primarily depends on which cranial nerve(s)?', '["Cranial nerve XII only", "Cranial nerve VII only", "Cranial nerves IX and X", "Cranial nerves I and II"]'::jsonb, 2, 'The glossopharyngeal (IX) and vagus (X) nerves mediate the sensory and motor components of the gag reflex, relevant to airway protection assessment.', 'PON 411 · Anatomy & Physiology'),
(1, 46, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The 6th cranial nerve is the:', '["Trigeminal nerve", "Facial nerve", "Oculomotor nerve", "Abducent nerve"]'::jsonb, 3, 'Cranial nerve VI, the abducent (abducens) nerve, supplies the lateral rectus, which abducts the eye.', 'PON 411 · Anatomy & Physiology'),
(1, 47, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Most nutrient absorption occurs in the:', '["Small intestine", "Large intestine", "Stomach", "Oesophagus"]'::jsonb, 0, 'The small intestine, with its vast surface area from villi and microvilli, is the primary site of digestion and nutrient absorption.', 'PON 411 · Anatomy & Physiology'),
(1, 48, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Vital cardiorespiratory centres are located in the:', '["Cerebellum", "Occipital lobe", "Hypothalamus only", "Medulla oblongata"]'::jsonb, 3, 'The medulla oblongata houses the cardiac and respiratory centres that regulate heart rate, blood pressure, and breathing rhythm.', 'PON 411 · Anatomy & Physiology'),
(1, 49, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The seminal vesicle measures about ______ in length.', '["4 cm", "3 cm", "10 cm", "5 cm"]'::jsonb, 3, 'Each seminal vesicle is a coiled sac about 5 cm long, lying behind the bladder. It contributes about 60–70% of semen volume.', 'PON 411 · Anatomy & Physiology'),
(1, 50, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Transitional epithelium of the urinary bladder is best described as:', '["A single, non-stratified layer", "Containing a special elastic substance", "Changing from cuboidal to columnar", "Changing shape depending on bladder fullness"]'::jsonb, 3, 'Transitional epithelium (urothelium) is stratified and changes shape, from dome-shaped to flattened, as the bladder fills and stretches.', 'PON 411 · Anatomy & Physiology'),
(1, 51, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Endogenous infection means infection caused by:', '["The patient''s own normal flora", "Organisms from another patient", "Contaminated instruments only", "Visitors only"]'::jsonb, 0, 'Gut bacteria can infect abdominal wounds.', 'GSM 402 · Microbiology & Infection Control'),
(1, 52, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Theatre staff with diarrhoea and vomiting should:', '["Work only in the recovery room", "Stay off work until 48 hours after symptoms stop", "Take antibiotics and continue", "Work as normal with gloves"]'::jsonb, 1, 'This prevents outbreaks such as norovirus.', 'GSM 402 · Microbiology & Infection Control'),
(1, 53, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Prophylactic antibiotics for surgical site infection prevention are most effective when administered:', '["Only after signs of infection appear", "Within about 60 minutes before surgical incision", "More than 24 hours after surgery", "Never, as they provide no benefit"]'::jsonb, 1, 'Prophylactic antibiotics are typically given within about 60 minutes before incision to achieve adequate tissue concentration during the period of highest contamination risk.', 'GSM 402 · Microbiology & Infection Control'),
(1, 54, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Povidone-iodine kills microorganisms by:', '["Releasing free iodine that damages microbial proteins", "Freezing the bacteria", "Starving the bacteria", "Increasing their growth"]'::jsonb, 0, 'It must dry on the skin to work fully.', 'GSM 402 · Microbiology & Infection Control'),
(1, 55, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Standard precautions require eye protection when:', '["Writing notes", "Walking in the corridor", "Talking to patients", "There is risk of splashes of blood or body fluids"]'::jsonb, 3, 'Goggles or face shields protect mucous membranes.', 'GSM 402 · Microbiology & Infection Control'),
(1, 56, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A carrier of infection is a person who:', '["Cannot spread infection", "Has been vaccinated", "Has severe symptoms only", "Harbours the organism without symptoms and can spread it"]'::jsonb, 3, 'Nasal MRSA carriers are an example.', 'GSM 402 · Microbiology & Infection Control'),
(1, 57, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Antibiotic resistance is increased by:', '["Good wound care", "Hand washing", "Vaccination", "Inappropriate and incomplete antibiotic use"]'::jsonb, 3, 'Antimicrobial stewardship reduces resistance.', 'GSM 402 · Microbiology & Infection Control'),
(1, 58, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Hepatitis A is mainly spread by:', '["Blood transfusion only", "Airborne droplets", "Sexual contact only", "The faecal-oral route"]'::jsonb, 3, 'Good hygiene and vaccination prevent it.', 'GSM 402 · Microbiology & Infection Control'),
(1, 59, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Droplet precautions, typically requiring a surgical mask, are appropriate for a patient with:', '["MRSA colonisation", "C. difficile infection", "Influenza", "Active pulmonary tuberculosis"]'::jsonb, 2, 'Droplet precautions with a surgical mask are used for pathogens spread via larger respiratory droplets over short distances, such as influenza.', 'GSM 402 · Microbiology & Infection Control'),
(1, 60, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Staphylococcus aureus on Gram stain appears as:', '["Gram-negative rods", "Gram-positive cocci in clusters", "Gram-positive cocci in chains", "Gram-negative diplococci"]'::jsonb, 1, 'Streptococci form chains.', 'GSM 402 · Microbiology & Infection Control'),
(1, 61, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Cholera causes:', '["Rash", "Bloody diarrhoea with fever only", "Jaundice", "Profuse watery diarrhoea and severe dehydration"]'::jsonb, 3, 'Oral or IV rehydration is the main treatment.', 'GSM 402 · Microbiology & Infection Control'),
(1, 62, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A wound swab for culture should be taken:', '["From dry dressing material", "After cleaning off surface debris, from viable tissue", "Without gloves", "After applying antiseptic to the wound bed"]'::jsonb, 1, 'Label and send promptly.', 'GSM 402 · Microbiology & Infection Control'),
(1, 63, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Fasciitis is commonly characterised as which type of infection?', '["Polymicrobial", "Entity microbial", "Gram-negative microbial", "Mono-microbial"]'::jsonb, 0, 'Necrotising fasciitis type I, the commonest form, is polymicrobial (mixed aerobes and anaerobes). Type II is usually group A strep.', 'GSM 402 · Microbiology & Infection Control'),
(1, 64, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Hepatitis B surface antibody (anti-HBs) above 10 mIU/mL after vaccination means:', '["The vaccine failed", "The person has active hepatitis", "The person is immune", "The person is a carrier"]'::jsonb, 2, 'Non-responders may need repeat vaccination.', 'GSM 402 · Microbiology & Infection Control'),
(1, 65, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A patient with confirmed tuberculosis requires which type of transmission-based precaution?', '["Airborne precautions", "Droplet precautions only", "No special precautions needed", "Contact precautions"]'::jsonb, 0, 'TB spreads via tiny airborne particles, requiring a negative-pressure room and fit-tested N95 respirator.', 'GSM 402 · Microbiology & Infection Control'),
(1, 66, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The incubation period is the time between:', '["Symptoms and recovery", "Diagnosis and treatment", "Infection and the first symptoms", "Birth and first infection"]'::jsonb, 2, 'It varies with each disease.', 'GSM 402 · Microbiology & Infection Control'),
(1, 67, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A viral infection cannot be treated by:', '["Supportive care", "Antiviral drugs", "Antibacterial antibiotics", "Vaccination for prevention"]'::jsonb, 2, 'Antibiotics do not kill viruses.', 'GSM 402 · Microbiology & Infection Control'),
(1, 68, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Tuberculosis is spread mainly by:', '["Mosquito bites", "Contaminated food", "Airborne droplet nuclei from coughing", "Skin contact only"]'::jsonb, 2, 'Use N95 respirators for airborne precautions.', 'GSM 402 · Microbiology & Infection Control'),
(1, 69, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Passive immunity is given by:', '["Natural infection", "Ready-made antibodies such as immunoglobulin", "A vaccine", "Antibiotics"]'::jsonb, 1, 'It works immediately but is short-lived.', 'GSM 402 · Microbiology & Infection Control'),
(1, 70, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Herd immunity means that:', '["Vaccines are not needed", "Only animals are immune", "Enough people are immune to protect those who are not", "All people have the disease"]'::jsonb, 2, 'It protects infants and immunocompromised people.', 'GSM 402 · Microbiology & Infection Control'),
(1, 71, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'The motor contraction called fasciculation is seen after the use of one of the following', '["Pavlun", "Suxamethonium", "Pethadine", "Marcaine"]'::jsonb, 1, 'Fasciculations (visible muscle twitching) are a characteristic effect of succinylcholine (suxamethonium) after administration.', 'PAN 414 · Anaesthesia'),
(1, 72, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Laryngeal mask air way is not used in one of the following cases', '["Patient with operation in lower part of the body", "Patient with operation in face", "Patient with short period operation", "Patient with full stomach"]'::jsonb, 3, 'A laryngeal mask airway does not protect against aspiration and is avoided in patients with a full stomach or high aspiration risk.', 'PAN 414 · Anaesthesia'),
(1, 73, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'The suffix ''E'' in an ASA classification (e.g. ASA II E) means:', '["The patient has epilepsy", "The patient is an organ donor", "The patient is elderly", "The surgery is an emergency"]'::jsonb, 3, 'Emergency surgery carries higher risk at any ASA level.', 'PAN 414 · Anaesthesia'),
(1, 74, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Thiopentone is absolutely contraindicated in:', '["Raised intracranial pressure", "Epilepsy", "Acute porphyria", "Day-case surgery"]'::jsonb, 2, 'Barbiturates can trigger a porphyric crisis.', 'PAN 414 · Anaesthesia'),
(1, 75, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Ventilation-perfusion (V/Q) mismatch during anaesthesia can result in:', '["No clinical effect", "Only affecting blood pressure, not oxygenation", "Impaired oxygenation despite adequate ventilator settings", "Improved gas exchange"]'::jsonb, 2, 'A mismatch between ventilated alveoli and perfused capillaries impairs effective gas exchange, contributing to hypoxaemia even with seemingly adequate ventilation.', 'PAN 414 · Anaesthesia'),
(1, 76, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'A normal end-tidal CO₂ in a ventilated healthy adult is about:', '["35–45 mmHg (4.5–6 kPa)", "0 mmHg", "5–10 mmHg (0.7–1.3 kPa)", "80–100 mmHg (10–13 kPa)"]'::jsonb, 0, 'No trace means the tube is not in the trachea or there is no cardiac output.', 'PAN 414 · Anaesthesia'),
(1, 77, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'A common oral endotracheal tube size for an adult woman is:', '["5.0 mm internal diameter", "7.0–7.5 mm internal diameter", "10.0–10.5 mm internal diameter", "4.0–4.5 mm internal diameter"]'::jsonb, 1, 'Adult men usually take 8.0–8.5 mm.', 'PAN 414 · Anaesthesia'),
(1, 78, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which local anaesthetic belongs to the ester group?', '["Procaine", "Mepivacaine", "Bupivacaine", "Lignocaine"]'::jsonb, 0, 'Procaine is an ester. Amides have two "i"s in their name: lidocaine, bupivacaine, mepivacaine.', 'PAN 414 · Anaesthesia'),
(1, 79, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'The Difficult Airway Society (DAS) guidelines'' Plan B after failed intubation is:', '["Proceed directly to surgery without any airway device in place", "Insert a supraglottic airway to maintain oxygenation", "Wake the patient without oxygen", "Keep trying laryngoscopy many times"]'::jsonb, 1, 'Plan C is face-mask ventilation; Plan D is front-of-neck access.', 'PAN 414 · Anaesthesia'),
(1, 80, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'The maximum recommended dose of bupivacaine is about:', '["2 mg/kg", "7 mg/kg with adrenaline", "20 mg/kg", "0.2 mg/kg"]'::jsonb, 0, 'It is particularly cardiotoxic in overdose.', 'PAN 414 · Anaesthesia'),
(1, 81, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'A patient on prophylactic LMWH (e.g. enoxaparin) should usually have neuraxial block no sooner than:', '["30 minutes after the last dose", "7 days after the last dose", "12 hours after the last dose", "2 hours after the last dose"]'::jsonb, 2, 'Treatment doses need about 24 hours, to reduce epidural haematoma risk.', 'PAN 414 · Anaesthesia'),
(1, 82, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'After an epidural, new severe back pain with leg weakness should make the nurse suspect:', '["Epidural haematoma or abscess needing urgent MRI", "Simple muscle strain from the position during the procedure", "Normal epidural effect", "Allergy to the dressing"]'::jsonb, 0, 'Delay can cause permanent paralysis.', 'PAN 414 · Anaesthesia'),
(1, 83, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'A patient is receiving Midazolam for sedation. The nurse knows that Midazolam is a:', '["Benzodiazepine", "Opioid analgesic", "Beta-blocker", "Neuromuscular blocking agent"]'::jsonb, 0, 'Midazolam is a benzodiazepine, which is a class of drugs that acts on the central nervous system to produce sedation and amnesia. It is commonly used for short-term sedation and anxiolysis.', 'PAN 414 · Anaesthesia'),
(1, 84, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'In Nigeria and the UK, a medical oxygen cylinder is colour coded:', '["Blue body with blue shoulder", "Black body with white shoulder", "Orange body with grey shoulder", "Grey body with black shoulder"]'::jsonb, 1, 'N₂O is blue; Entonox is blue with blue and white shoulders.', 'PAN 414 · Anaesthesia'),
(1, 85, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Postoperative shivering is most commonly related to:', '["Intraoperative hypothermia", "Hyperglycaemia", "Overhydration", "Excessive analgesia"]'::jsonb, 0, 'Shivering after anaesthesia is most often a thermoregulatory response to intraoperative heat loss and residual anaesthetic effects on thermoregulation.', 'PAN 414 · Anaesthesia'),
(1, 86, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'A contraindication to neuraxial (spinal/epidural) anaesthesia is:', '["Mild anxiety", "Patient preference for regional technique", "Coagulopathy or infection at the injection site", "Stable vital signs"]'::jsonb, 2, 'Coagulopathy risks epidural/spinal haematoma, and local infection risks introducing pathogens into the CSF or epidural space — both are recognised contraindications.', 'PAN 414 · Anaesthesia'),
(1, 87, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'To reduce the risk of aspiration during induction of anaesthesia in an at-risk patient, the nurse/anaesthetist should ensure:', '["The patient is positioned flat on their back with no head elevation regardless of risk", "Adequate fasting time has been observed and rapid sequence induction is used if indicated", "The patient has recently eaten a full meal", "No airway equipment is prepared"]'::jsonb, 1, 'Adequate fasting and, where indicated, rapid sequence induction with cricoid pressure reduce aspiration risk in at-risk patients.', 'PAN 414 · Anaesthesia'),
(1, 88, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Methaemoglobinaemia is classically caused by which local anaesthetic?', '["Prilocaine", "Bupivacaine", "Lignocaine", "Procaine"]'::jsonb, 0, 'Prilocaine''s metabolite (o-toluidine) oxidises haemoglobin to methaemoglobin, especially at high doses.', 'PAN 414 · Anaesthesia'),
(1, 89, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Minimum alveolar concentration (MAC) of an inhalational agent is a measure of its:', '["Toxicity", "Potency", "Cost", "Duration"]'::jsonb, 1, 'MAC is the alveolar concentration that prevents movement in 50% of subjects to a surgical stimulus. A lower MAC means a more potent agent.', 'PAN 414 · Anaesthesia'),
(1, 90, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Minimum monitoring during general anaesthesia includes ECG, NIBP, pulse oximetry and:', '["Capnography and anaesthetic gas analysis", "Central venous pressure in every case", "Urine output and core temperature in every case", "Arterial line in every case"]'::jsonb, 0, 'A trained anaesthetist must be present throughout.', 'PAN 414 · Anaesthesia'),
(1, 91, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Propofol as an induction agent is characterised by:', '["Being the treatment for malignant hyperthermia", "Slow onset and long duration of action", "Rapid onset, rapid recovery, and antiemetic properties", "Causing hypertension in most patients"]'::jsonb, 2, 'Propofol has a rapid onset and offset due to fast redistribution and metabolism, and it has mild antiemetic properties, making it popular for induction and maintenance.', 'PAN 414 · Anaesthesia'),
(1, 92, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'A heat and moisture exchanger (HME) filter in the breathing circuit:', '["Removes CO₂ from expired gas in place of soda lime", "Warms and humidifies inspired gas and filters microbes", "Measures oxygen concentration", "Adds volatile agent to the gas"]'::jsonb, 1, 'Check it does not become blocked with secretions.', 'PAN 414 · Anaesthesia'),
(1, 93, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Rapid sequence induction is primarily indicated for patients:', '["Undergoing elective minor surgery", "Who are fasted for over 12 hours", "With no comorbidities", "At high risk of pulmonary aspiration"]'::jsonb, 3, 'RSI minimises the time between loss of airway reflexes and securing the airway, protecting patients at high aspiration risk (e.g. full stomach, bowel obstruction, pregnancy) from regurgitation.', 'PAN 414 · Anaesthesia'),
(1, 94, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Atracurium is muscle relaxant which is', '["Metabolized by liver", "Metabolized by kidney", "Metabolized by Hoffman degradation", "Contraindicated in renal transplant"]'::jsonb, 2, 'Atracurium is uniquely metabolised via Hofmann elimination (spontaneous degradation independent of liver/kidney function), useful in organ failure.', 'PAN 414 · Anaesthesia'),
(1, 95, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'A patient is on a neuromuscular blocking agent. The nurse knows that this medication is used to:', '["Cause muscle paralysis", "Decrease anxiety", "Relieve pain", "Induce sedation"]'::jsonb, 0, 'Neuromuscular blocking agents are used to paralyze the patient''s muscles. They do not have a sedative or analgesic effect. The patient may still be conscious and able to feel pain and anxiety, so they must be used in conjunction with a sedative and an analgesic.', 'PAN 414 · Anaesthesia'),
(1, 96, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Propofol is best used for', '["Hypertensive patient", "Regional anaesthesia", "Recovery from anaesthesia", "Induction of anaesthesia"]'::jsonb, 3, 'Propofol''s rapid onset and clear-headed recovery profile make it a popular agent for induction of anaesthesia.', 'PAN 414 · Anaesthesia'),
(1, 97, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Poor functional capacity before surgery is suggested by inability to:', '["Walk across a room", "Talk while sitting", "Sit up in bed unaided after a night''s sleep", "Climb two flights of stairs (less than 4 METs)"]'::jsonb, 3, 'Poor exercise tolerance predicts more complications.', 'PAN 414 · Anaesthesia'),
(1, 98, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Nasal airway is not indicated in one of the following', '["Comatose patient", "Pediatric patient", "Basal skull fracture", "Full conscious patient"]'::jsonb, 2, 'A nasal airway risks intracranial passage and is avoided in suspected basal skull fracture, particularly with signs like CSF rhinorrhoea or panda eyes.', 'PAN 414 · Anaesthesia'),
(1, 99, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'Muscle pains (myalgia) the day after surgery are a known side effect of:', '["Suxamethonium", "Rocuronium", "Fentanyl", "Propofol given at induction"]'::jsonb, 0, 'Fasciculations from depolarisation cause the myalgia.', 'PAN 414 · Anaesthesia'),
(1, 100, 'Perioperative Mock — Day 7 Morning (Nov 2026)', 'PAN 414 · Anaesthesia', 'A characteristic side effect of alpha-2 adrenergic agonists such as dexmedetomidine is:', '["Malignant hyperthermia", "Tachycardia", "Bradycardia and hypotension", "Severe bronchospasm"]'::jsonb, 2, 'Alpha-2 agonists (dexmedetomidine, clonidine, xylazine) give sedation with some analgesia but can cause bradycardia and hypotension.', 'PAN 414 · Anaesthesia'),
(2, 1, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The specific antidote for opioid overdose (e.g. morphine, fentanyl) is:', '["Activated charcoal", "N-acetylcysteine", "Flumazenil", "Naloxone"]'::jsonb, 3, 'Naloxone is a competitive opioid receptor antagonist used to reverse opioid-induced respiratory depression.', 'PAN 412 · Pharmacology'),
(2, 2, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Before elective surgery, aspirin given for secondary heart prevention is usually:', '["Doubled on the day of surgery", "Continued, unless the surgeon advises otherwise", "Replaced with warfarin", "Always stopped 4 weeks before"]'::jsonb, 1, 'Stopping it risks coronary events; clopidogrel is often stopped 7 days before.', 'PAN 412 · Pharmacology'),
(2, 3, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient develops serotonin syndrome after being started on two serotonergic medications simultaneously. The nurse should recognise this presentation includes:', '["No clinical significance requiring only observation", "Bradycardia and hypotension with no other findings", "Agitation, hyperthermia, tremor, and autonomic instability", "Improved mental status"]'::jsonb, 2, 'Serotonin syndrome presents with agitation, hyperthermia, neuromuscular abnormalities (tremor, clonus) and autonomic instability, requiring prompt recognition and discontinuation of the causative agents.', 'PAN 412 · Pharmacology'),
(2, 4, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The concentration of epinephrine used for endoscopic injection in bleeding ulcers is:', '["1:1,000", "1:10,000", "1:1,000,000", "1:100,000"]'::jsonb, 1, 'This diluted concentration is strong enough to cause local vasoconstriction and stop bleeding without excessive systemic effect.', 'PAN 412 · Pharmacology'),
(2, 5, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The first-line vasopressor of choice in septic shock is:', '["Norepinephrine", "Vasopressin", "Adrenaline", "Dopamine"]'::jsonb, 0, 'Norepinephrine is the preferred first-choice drug to raise blood pressure in septic shock.', 'PAN 412 · Pharmacology'),
(2, 6, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on long-term diuretic therapy develops muscle weakness, cramping, and an irregular pulse. The nurse should suspect an electrolyte disturbance, most likely:', '["Hypokalaemia", "Hyperglycaemia", "Hypercalcaemia", "Hypernatraemia"]'::jsonb, 0, 'Muscle weakness, cramping and arrhythmia in a patient on diuretics (especially loop/thiazide) are classic signs of hypokalaemia, a common diuretic side effect.', 'PAN 412 · Pharmacology'),
(2, 7, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A 53-year-old patient who is receiving ibuprofen 400 mg twice a day, for chronic, low back pain develops lower-extremity oedema. The pain management nurse suspects that the oedema is caused by:', '["An increase in plasma proteins.", "A decrease in renal function", "A low creatinine level.", "An increase in glomerular filtration rate"]'::jsonb, 1, 'NSAIDs can reduce renal blood flow/function, causing fluid retention and oedema.', 'PAN 412 · Pharmacology'),
(2, 8, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Warfarin before elective surgery is usually stopped about:', '["5 days before, with INR checked the day before", "On the morning of surgery", "1 month before", "6 hours before"]'::jsonb, 0, 'High-risk patients may need bridging with heparin.', 'PAN 412 · Pharmacology'),
(2, 9, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'which of this is a narcotic analgesics', '["Ibuprofen", ".Morphine", "Halothen", "Acetamophine"]'::jsonb, 1, 'Morphine is a classic narcotic (opioid) analgesic.', 'PAN 412 · Pharmacology'),
(2, 10, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The critical care nurse follows the recommended protocol for preventing constipation when starting a patient on opioids by', '["Increasing fluids and exercise.", "Giving the patient enemas as needed.", "Adding bulk fibre to the diet", "Using a bowel stimulant and stool softener."]'::jsonb, 3, 'A bowel stimulant plus stool softener is the standard combination to prevent opioid-induced constipation.', 'PAN 412 · Pharmacology'),
(2, 11, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Benzylpenicillin is the chemical name for:', '["Phenethicillin", "Penicillin V", "Penicillin G", "Penicillin F"]'::jsonb, 2, 'Benzylpenicillin is penicillin G. Penicillin V is phenoxymethylpenicillin.', 'PAN 412 · Pharmacology'),
(2, 12, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Ipratropium bromide is used in the management of:', '["Acute gastroenteritis", "Acute peptic ulcer disease", "Acute asthmatic attack", "Acute bronchopneumonia"]'::jsonb, 2, 'Ipratropium bromide is an inhaled anticholinergic bronchodilator, added to salbutamol in acute severe asthma and used in COPD.', 'PAN 412 · Pharmacology'),
(2, 13, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which history requires caution when giving paracetamol (acetaminophen)?', '["Allergy to aspirin", "Occasional alcohol use", "Gastric irritation with bleeding", "Hepatitis B"]'::jsonb, 3, 'Paracetamol is metabolised by the liver and is hepatotoxic. Use it with caution in liver disease such as hepatitis B.', 'PAN 412 · Pharmacology'),
(2, 14, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Specific antidote in paracetamol poisoning is', '["Desferroxamine", "Acetyl cysteine", "Activated charcoal", "Naloxone"]'::jsonb, 1, 'Acetylcysteine is the specific antidote for paracetamol overdose.', 'PAN 412 · Pharmacology'),
(2, 15, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on long-term steroids having major surgery needs:', '["Only oral potassium", "No change at all", "Extra steroid cover (e.g. IV hydrocortisone) around surgery", "All steroids stopped a week before"]'::jsonb, 2, 'The suppressed adrenal cannot mount a stress response.', 'PAN 412 · Pharmacology'),
(2, 16, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient in septic shock requires norepinephrine. Which effect is PRIMARY for this drug?', '["Renal artery dilation", "Vasoconstriction", "Increased myocardial contractility", "Bronchodilation"]'::jsonb, 1, 'Norepinephrine is an α-agonist that increases SVR and MAP in septic shock. Inotropy is secondary.', 'PAN 412 · Pharmacology'),
(2, 17, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'When starting a patient on opioids, the recommended protocol for preventing constipation is to:', '["Increase fluids and exercise only", "Give enemas as needed", "Add bulk fibre to the diet", "Use a bowel stimulant and a stool softener"]'::jsonb, 3, 'Opioid-induced constipation is prevented with a stimulant laxative plus a stool softener from the start. Fibre alone may worsen it.', 'PAN 412 · Pharmacology'),
(2, 18, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient receiving dexmedetomidine for sedation may experience:', '["Bradycardia and hypotension", "Respiratory depression", "Hypertension and tachycardia", "Agitation"]'::jsonb, 0, 'Dexmedetomidine (α2-agonist) causes sympatholysis, leading to bradycardia/hypotension.', 'PAN 412 · Pharmacology'),
(2, 19, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient with opioid overdose has respiratory depression. Naloxone is administered but wears off in 30 minutes. Which action is BEST?', '["Give a second naloxone dose", "Intubate the patient", "Start flumazenil", "Switch to naltrexone"]'::jsonb, 0, 'Naloxone has a short half-life; redosing is needed for long-acting opioids (e.g., methadone).', 'PAN 412 · Pharmacology'),
(2, 20, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Drugs that suppress or relieve coughing without necessarily treating the cause are:', '["Bronchodilators", "Expectorants", "Antibiotics", "Antitussive agents"]'::jsonb, 3, 'Antitussives suppress the cough reflex without treating the underlying cause.', 'PAN 412 · Pharmacology'),
(2, 21, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on a β-blocker has hypoglycemia. Which sign may be masked?', '["Tremors", "Diaphoresis", "Tachycardia", "Hunger"]'::jsonb, 2, 'β-blockers blunt tachycardia (adrenergic response) in hypoglycemia.', 'PAN 412 · Pharmacology'),
(2, 22, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A client with asthma is taking a theophylline bronchodilator. Which breakfast item should the nurse discuss with the client?', '["Eggs", "Coffee", "Bananas", "Toast"]'::jsonb, 1, 'Caffeine, like theophylline, is a methylxanthine. Coffee can add to theophylline''s stimulant and toxic effects (tachycardia, tremor).', 'PAN 412 · Pharmacology'),
(2, 23, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on furosemide (a loop diuretic) should be monitored closely for which electrolyte disturbance?', '["Hypokalaemia", "Hyperkalaemia", "Hypercalcaemia only", "Hypernatraemia only"]'::jsonb, 0, 'Loop diuretics like furosemide promote potassium loss and commonly cause hypokalaemia, requiring regular electrolyte monitoring.', 'PAN 412 · Pharmacology'),
(2, 24, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which antibacterial should be avoided with d-tubocurarine because it enhances neuromuscular blockade?', '["Norfloxacin", "Cefotaxime", "Streptomycin", "Doxycycline"]'::jsonb, 2, 'Aminoglycosides such as streptomycin reduce acetylcholine release and potentiate non-depolarising blockers, prolonging paralysis.', 'PAN 412 · Pharmacology'),
(2, 25, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'One milligram (1mg) is prescribed, tablets are 500 micrograms: how many tablets will you give?', '["2µs", "2tabs", "2µg", "2mg"]'::jsonb, 1, '1mg = 1000mcg; 1000mcg ÷ 500mcg per tablet = 2 tablets.', 'PAN 412 · Pharmacology'),
(2, 26, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A post-operative COPD patient who retains CO₂ should have oxygen titrated to:', '["SpO₂ 100% at all times", "SpO₂ 70–75%", "No oxygen at all", "SpO₂ 88–92%"]'::jsonb, 3, 'Too much oxygen can worsen hypercapnia.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 27, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Each PACU bay should have, as a minimum:', '["Oxygen, suction, a self-inflating bag and monitors", "Only a manual blood pressure cuff and stethoscope", "Only a bed, a chair and a call bell for the patient", "A ventilator and a dialysis machine in every bay"]'::jsonb, 0, 'Emergency drugs and a defibrillator must be immediately available.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 28, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Having a parent present when a child wakes in PACU mainly helps to:', '["Reduce the child''s distress on waking", "Reduce the number of staff needed in the recovery room", "Replace the need for any monitoring", "Shorten the total anaesthetic time"]'::jsonb, 0, 'Follow unit policy; the airway must be safe first.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 29, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Paracetamol IV for an adult over 50 kg after surgery is usually given at:', '["5 g as a single dose, then none", "100 mg once daily (maximum 100 mg in 24 hours)", "1 g every 6 hours (max 4 g a day)", "10 g every 2 hours (no maximum)"]'::jsonb, 2, 'Reduce dose in low weight or liver disease.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 30, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Signs that a patient in PACU may have residual neuromuscular blockade include:', '["Pinpoint pupils with a slow pulse only", "Being unable to lift the head for 5 seconds", "A high temperature with shivering and fast breathing", "A strong cough and normal deep breathing"]'::jsonb, 1, 'Give oxygen, support breathing and inform the anaesthetist.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 31, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'After tonsillectomy, frequent swallowing in a sleeping child in PACU suggests:', '["Pain from the throat only", "Normal recovery after surgery", "Hunger after fasting", "Bleeding from the tonsil bed"]'::jsonb, 3, 'Look in the mouth, check pulse and call the surgeon.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 32, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU has a heart rate of 38/min with hypotension. The first-line drug is:', '["Metoprolol 5 mg IV", "Adenosine 6 mg IV", "Atropine 0.5 mg IV", "Amiodarone 300 mg IV"]'::jsonb, 2, 'Repeat as needed; look for causes such as vagal stimulation or high spinal.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 33, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'After a long operation in the prone position, the PACU nurse checks:', '["Only the feet for colour and warmth, as the rest was padded", "Only the abdomen for the wound site", "Eyes, face, breasts and genitals for pressure", "Only the back of the head for hair loss"]'::jsonb, 2, 'Report any vision loss urgently.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 34, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient with a chest tube has continuous bubbling in the water seal chamber. The nurse should:', '["Clamp the tube", "Increase suction", "Notify the provider", "Check for an air leak"]'::jsonb, 3, 'Continuous bubbling indicates an air leak (e.g., from system disconnection).', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 35, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A post-operative patient with a chest drain arrives in PACU. The nurse ensures the drain bottle is:', '["Lying on its side under the trolley so that it does not fall over", "Below chest level with the water seal intact", "Clamped for the whole stay in recovery", "Above the patient''s head on a drip stand"]'::jsonb, 1, 'Note bubbling, swinging and drainage volume.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 36, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient arriving in PACU with an airway device in place needs:', '["A porter to watch the monitor from the desk", "No observation if all the monitors are attached", "One nurse for every four patients in the bay", "One-to-one nursing until airway reflexes return"]'::jsonb, 3, 'Never leave a patient with an airway device unattended.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 37, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A PACU discharge criterion for pain is that pain is:', '["Severe but expected after major surgery", "Controlled to an acceptable level, with a plan", "Absent completely in every single patient", "Not assessed if the patient is drowsy, as they cannot report it"]'::jsonb, 1, 'Pain scores and analgesia given must be recorded.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 38, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU says ''I can''t breathe'' but has normal SpO₂ and talks in full sentences. The nurse should:', '["Intubate immediately to protect the airway", "Give a sedative straight away to calm them", "Assess fully, reassure and look for a cause", "Ignore the complaint, as an SpO₂ that is normal means there is no problem"]'::jsonb, 2, 'Anxiety is common but must not be assumed.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 39, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'FLACC is a pain assessment tool used mainly for:', '["Measuring sedation depth in ICU patients", "Young children and non-verbal patients", "Fully alert adults who can talk", "Assessing nausea and vomiting"]'::jsonb, 1, 'Face, Legs, Activity, Cry, Consolability.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 40, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Inadequate pain control after surgery can lead to:', '["Shallow breathing, atelectasis and slow mobilisation", "Lower blood pressure and a slower heart rate after surgery", "Faster wound healing and a shorter hospital stay", "Better sleep on the first night after surgery"]'::jsonb, 0, 'Good analgesia allows deep breathing and coughing.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 41, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A PACU nurse hands over a patient to the ward nurse. The handover should include:', '["Only the surgeon''s name and phone number, in case the ward needs help", "Only the patient''s name and hospital number", "Procedure, anaesthesia, drugs, fluids, concerns and plan", "Only the time of arrival in the recovery room"]'::jsonb, 2, 'A structured tool such as SBAR reduces omissions.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 42, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU who is shivering should first receive:', '["Oxygen and active warming", "Removal of all blankets", "IV potassium chloride given rapidly", "Cold IV fluids"]'::jsonb, 0, 'Shivering raises oxygen demand greatly.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 43, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU complains of chest pain with ST depression on the monitor. The nurse should:', '["Give a laxative, as the pain may be from wind", "Wait to see whether the pain settles on its own", "Give oxygen if needed, do a 12-lead ECG and call the doctor", "Send the patient to the ward for observation and a review in the morning"]'::jsonb, 2, 'Perioperative myocardial ischaemia is often silent.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 44, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Dexamethasone used for PONV prophylaxis is best given:', '["Only after the patient vomits", "At discharge from hospital", "The week before surgery", "At induction of anaesthesia"]'::jsonb, 3, 'It works slowly; check glucose in diabetics.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 45, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU who had a peripheral nerve block is given a falls risk because:', '["The blocked limb is numb and weak", "The patient cannot see properly", "The patient is deaf after surgery", "The patient has no IV line in place"]'::jsonb, 0, 'Help the patient when they first stand.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 46, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A post-thyroidectomy patient in PACU develops a rapidly enlarging neck swelling and stridor. The first action is to:', '["Give oral fluids to help the patient swallow more easily", "Wait for the surgeon''s next ward round to review the wound", "Apply a tight pressure bandage around the patient''s neck to stop the bleeding", "Call for help and open the sutures to release the haematoma"]'::jsonb, 3, 'Clip or suture removers should be at the bedside.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 47, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A nurse is caring for a patient who is post-anesthesia. The primary nursing responsibility in the post-anesthesia care unit (PACU) is to:', '["Administer a sedative to keep the patient asleep", "Allow the patient to get up and walk around immediately", "Feed the patient a light meal", "Monitor the patient''s vital signs and respiratory status"]'::jsonb, 3, 'In the PACU, the nurse''s priority is to monitor for complications from anesthesia, particularly respiratory depression and hypotension. The nurse must closely monitor the patient''s vital signs, level of consciousness, and respiratory status to ensure a safe recovery.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 48, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Oxygen given by face mask in PACU should be at a flow of at least:', '["0.5 L/min, to save oxygen and prevent drying of the airway", "5 L/min, to avoid rebreathing CO₂", "60 L/min, the maximum flow", "1 L/min, as for nasal cannula"]'::jsonb, 1, 'Lower flows let exhaled CO₂ build up in the mask.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 49, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU is slow to wake 45 minutes after surgery. The nurse should first check:', '["Airway, breathing, SpO₂, glucose and temperature", "The theatre list for the next case today", "Only the wound dressing for any bleeding", "Whether the family has arrived to visit, so they can help wake the patient"]'::jsonb, 0, 'Causes include residual drugs, hypoglycaemia, hypothermia, hypercapnia and stroke.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 50, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU suddenly becomes hypotensive with wheeze, rash and facial swelling after IV antibiotic. The first drug is:', '["IV morphine 10 mg", "IM adrenaline 0.5 mg", "IV furosemide 40 mg", "Oral antihistamine only"]'::jsonb, 1, 'Stop the antibiotic, give oxygen, fluids and call for help.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 51, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Pain at the left shoulder tip after blunt abdominal trauma (Kehr''s sign) suggests:', '["Liver laceration on the right side", "Acute appendicitis with perforation", "Splenic rupture irritating the diaphragm", "A renal stone in the left ureter irritating the kidney"]'::jsonb, 2, 'Blood under the diaphragm refers pain to the shoulder.', 'PON 416 · General Surgery'),
(2, 52, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Which of the following is not a sign of acute appendicitis', '["Rovsing''s sign", "Obturator sign", "Murphy''s sign", "Pointing sign"]'::jsonb, 2, 'Murphy''s sign relates to gallbladder disease, not appendicitis.', 'PON 416 · General Surgery'),
(2, 53, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'The Glasgow (Imrie) criteria are used to assess the severity of:', '["Appendicitis", "Acute pancreatitis", "Head injury", "Burns depth"]'::jsonb, 1, 'Three or more positive criteria suggest severe pancreatitis.', 'PON 416 · General Surgery'),
(2, 54, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Wound vacuum (negative pressure) therapy helps healing by:', '["Sealing the wound with tissue glue", "Removing exudate and helping granulation", "Cooling the wound to reduce pain and swelling", "Killing all the bacteria with heat"]'::jsonb, 1, 'It is used for large open or complex wounds.', 'PON 416 · General Surgery'),
(2, 55, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'The mesh used in hernia repair can become infected. Signs include:', '["Persistent discharge, redness and pain at the repair", "Headache only, with no wound signs", "Rapid weight gain over a few weeks", "Low blood sugar after meals and weight loss"]'::jsonb, 0, 'Removal of the mesh may be needed.', 'PON 416 · General Surgery'),
(2, 56, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'The purpose of preoperative carbimazole therapy before thyroidectomy is to:', '["Reduce gland firmness", "Decrease calcium level", "Achieve euthyroid state", "Reduce postoperative infection"]'::jsonb, 2, 'Carbimazole is given pre-operatively to bring the patient to a euthyroid (normal hormone) state before anaesthesia and surgery.', 'PON 416 · General Surgery'),
(2, 57, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'After abdominoperineal resection for low rectal cancer, the patient will have:', '["A permanent end colostomy", "A urostomy (ileal conduit)", "No stoma at all", "A temporary ileostomy"]'::jsonb, 0, 'The anus and rectum are removed.', 'PON 416 · General Surgery'),
(2, 58, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'A patient with obstructive jaundice having surgery is at increased risk of:', '["Pressure ulcers only, from long surgery", "Bleeding (low vitamin K) and renal failure", "Hypothermia only during the operation", "High blood sugar only after surgery, needing insulin"]'::jsonb, 1, 'Give vitamin K and keep the patient well hydrated.', 'PON 416 · General Surgery'),
(2, 59, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'A patient post-thyroidectomy suddenly develops stridor and dyspnea. The most likely cause is:', '["Laryngeal edema", "Hypocalcaemia", "Hyperkalaemia", "Anemia"]'::jsonb, 0, 'Sudden stridor and dyspnoea after thyroidectomy is most often due to laryngeal oedema narrowing the airway.', 'PON 416 · General Surgery'),
(2, 60, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'A typical sign of intestinal obstruction on abdominal X-ray is:', '["Free air seen under the diaphragm", "A completely normal gas pattern", "Dilated bowel loops with air-fluid levels", "Calcified kidneys on both sides of the spine"]'::jsonb, 2, 'Free air suggests perforation.', 'PON 416 · General Surgery'),
(2, 61, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'The invagination of segment of a bowel into another adjacent segment in Aminu, 6 months old baby is known as', '["Appendicitis", "Intussusception", "In-vaginitis", "Gastritis"]'::jsonb, 1, 'One bowel segment telescoping into an adjacent segment is intussusception.', 'PON 416 · General Surgery'),
(2, 62, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'A subphrenic abscess after laparotomy typically presents with:', '["Painless haematuria and loin pain", "Swinging fever, upper abdominal and shoulder tip pain", "Visual loss and headache with neck stiffness", "Leg weakness and numbness"]'::jsonb, 1, 'Ultrasound or CT confirms; drainage is needed.', 'PON 416 · General Surgery'),
(2, 63, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Helicobacter pylori eradication usually uses:', '["A proton pump inhibitor with two antibiotics", "Surgery in all patients to remove the ulcer", "Antacids alone for 2 weeks", "Steroids and antihistamines"]'::jsonb, 0, 'Eradication reduces ulcer recurrence.', 'PON 416 · General Surgery'),
(2, 64, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'McBurney''s point lies:', '["Just above the pubic symphysis in the midline", "In the left iliac fossa, below the umbilicus", "Midway between the xiphoid process and the umbilicus", "One-third of the way from the ASIS to the umbilicus"]'::jsonb, 3, 'Tenderness here is typical of appendicitis.', 'PON 416 · General Surgery'),
(2, 65, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Murphy''s sign (arrest of inspiration on palpation of the right upper quadrant) suggests:', '["Renal colic from a ureteric stone", "Acute appendicitis", "Splenic rupture", "Acute cholecystitis"]'::jsonb, 3, 'Ultrasound confirms gallbladder wall thickening and stones.', 'PON 416 · General Surgery'),
(2, 66, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Achalasia of the oesophagus causes:', '["Diarrhoea after drinking milk and eating fatty foods", "Vomiting of green bile after meals", "Pain only on eating fatty foods", "Difficulty swallowing both solids and liquids"]'::jsonb, 3, 'The lower oesophageal sphincter fails to relax.', 'PON 416 · General Surgery'),
(2, 67, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'A lipoma is:', '["An infected hair follicle", "A malignant skin cancer of the fat layer", "A blood clot under the skin", "A benign tumour of fat cells"]'::jsonb, 3, 'Usually soft, mobile and painless.', 'PON 416 · General Surgery'),
(2, 68, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'The ''five Ws'' of post-operative fever include Wind, Water, Wound, Walking and:', '["Weather and cold wards (hypothermia)", "Work stress and anxiety", "Weight loss before surgery", "Wonder drugs (drug reactions)"]'::jsonb, 3, 'Wind (day 1–2), Water/UTI (day 3–5), Wound (day 5–7), Walking/DVT (day 7–10).', 'PON 416 · General Surgery'),
(2, 69, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'The scoring tool commonly used to decide the urgency of endoscopy in upper GI bleeding is:', '["The Glasgow-Blatchford score", "The Braden score", "The Apgar score at 1 and 5 minutes", "The Glasgow Coma Scale"]'::jsonb, 0, 'The Rockall score predicts mortality after endoscopy.', 'PON 416 · General Surgery'),
(2, 70, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Preoperative teaching for thyroidectomy includes:', '["Neck support when turning", "Deep mouth breathing only", "Neck flexion exercises", "Avoidance of coughing"]'::jsonb, 0, 'Supporting the neck (avoiding strain) when turning or moving protects the fresh suture line.', 'PON 416 · General Surgery'),
(2, 71, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'A patient experiences a postoperative incisional hernia. What should be included in the nursing care plan?', '["Application of heat pads to the hernia site", "Encouraging lifting heavy objects", "Reinforcing the surgical incision with glue", "Promoting early ambulation"]'::jsonb, 3, 'Early ambulation reduces intra-abdominal pressure spikes from straining and supports overall recovery, forming part of hernia-risk-reducing postoperative care.', 'PON 416 · General Surgery'),
(2, 72, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Which of the following complications is thought to be the most common cause of appendicitis?', '["A fecalith", "Abdominal bowel swelling", "Internal bowel occlusion", "Bowel kinking"]'::jsonb, 0, 'A fecalith (hardened stool) obstructing the appendix is the most common cause of appendicitis.', 'PON 416 · General Surgery'),
(2, 73, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'A patient with a nasogastric tube on free drainage after bowel surgery is mainly being treated for:', '["Dehydration treatment", "Gastric decompression in ileus", "Hypoglycaemia correction", "Hypertension control after bowel surgery"]'::jsonb, 1, 'Measure and replace the losses.', 'PON 416 · General Surgery'),
(2, 74, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Early post-operative feeding after most bowel surgery (ERAS) is:', '["Given only by TPN at first", "Encouraged, as it speeds recovery", "Harmful in all patients, so it is delayed for a week", "Forbidden for at least 2 weeks"]'::jsonb, 1, 'It reduces infection and length of stay.', 'PON 416 · General Surgery'),
(2, 75, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 416 · General Surgery', 'Accidental removal of the parathyroid glands during thyroidectomy results in:', '["Hyperthyroidism", "Hypocalcaemia", "Hyperkalaemia", "Hypoglycaemia"]'::jsonb, 1, 'Without the parathyroids, blood calcium drops, causing Trousseau''s and Chvostek''s signs.', 'PON 416 · General Surgery'),
(2, 76, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A Dupuytren''s contracture is:', '["Thickened palmar fascia pulling fingers into flexion", "A fracture of the fifth metacarpal bone", "An infection of the pulp of the finger after a thorn injury", "A ruptured tendon at the base of the thumb"]'::jsonb, 0, 'Surgery (fasciectomy) is done when function is affected.', 'PON 417 · Trauma & Orthopaedics'),
(2, 77, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A shoulder dislocation most commonly occurs:', '["Inferiorly only", "Anteriorly", "Posteriorly", "Superiorly"]'::jsonb, 1, 'Check the axillary nerve (sensation over the deltoid).', 'PON 417 · Trauma & Orthopaedics'),
(2, 78, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A fracture of the fibular neck or a tight cast at the knee may injure the common peroneal nerve, causing:', '["Foot drop", "Wrist drop", "Loss of hearing", "Loss of hip flexion"]'::jsonb, 0, 'Pad the lateral knee and check dorsiflexion.', 'PON 417 · Trauma & Orthopaedics'),
(2, 79, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A plaster backslab differs from a full cast because it:', '["Covers the whole limb tightly all round", "Never needs checking after it has been applied by the nurse", "Is used only for fractures of the spine", "Is not circumferential, so it allows swelling"]'::jsonb, 3, 'It is often used in the first days after injury.', 'PON 417 · Trauma & Orthopaedics'),
(2, 80, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient who can bear partial weight on one leg using crutches usually uses:', '["A two-point gait without weight bearing", "No crutches at all", "A swing-through gait only", "A three-point gait"]'::jsonb, 3, 'Both crutches and the injured leg move together.', 'PON 417 · Trauma & Orthopaedics'),
(2, 81, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The Ponseti method is used to treat:', '["Club foot (talipes equinovarus)", "Hip dislocation in adults", "Scoliosis of the spine", "A fractured wrist in children"]'::jsonb, 0, 'Serial casting and a brace correct the foot.', 'PON 417 · Trauma & Orthopaedics'),
(2, 82, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Cauda equina syndrome after a disc prolapse is suggested by:', '["Saddle anaesthesia, retention and leg weakness", "Mild back stiffness in the morning that eases with movement", "Neck pain only, with no other signs", "Headache and fever with a stiff neck"]'::jsonb, 0, 'It is a surgical emergency needing urgent MRI.', 'PON 417 · Trauma & Orthopaedics'),
(2, 83, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A collar and cuff sling is mainly used for:', '["Ankle sprains and foot injuries", "Humeral neck or shaft fractures, where gravity helps", "Femoral shaft fractures in adults", "Fractured ribs after a fall, to splint the chest wall"]'::jsonb, 1, 'A broad arm sling supports forearm injuries.', 'PON 417 · Trauma & Orthopaedics'),
(2, 84, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'After hand surgery, the hand is kept elevated mainly to:', '["Increase bleeding", "Speed up anaesthesia", "Prevent nausea and vomiting", "Reduce swelling and pain"]'::jsonb, 3, 'Encourage finger movements unless told otherwise.', 'PON 417 · Trauma & Orthopaedics'),
(2, 85, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Thromboprophylaxis after total hip or knee replacement is important because:', '["They have a low risk of clots after surgery", "They bleed less than most other patients after surgery", "These patients have a high risk of DVT and PE", "They never need anticoagulants afterwards"]'::jsonb, 2, 'Use mechanical and drug prophylaxis as prescribed.', 'PON 417 · Trauma & Orthopaedics'),
(2, 86, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The classic triad of fat embolism syndrome is:', '["Hypotension, tachycardia, pallor", "Fever, cough, chest pain", "Jaundice, ascites, confusion", "Confusion, dyspnoea, petechiae"]'::jsonb, 3, 'Fat droplets from fractured bone marrow travel to lungs, brain, and skin capillaries, causing this classic combination.', 'PON 417 · Trauma & Orthopaedics'),
(2, 87, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'An open (compound) fracture should receive IV antibiotics:', '["Only after 48 hours, once cultures are back", "Only if pus appears in the wound", "As soon as possible, ideally within 1 hour", "Never; only surgery is needed for these"]'::jsonb, 2, 'Also give tetanus cover and cover the wound with a saline-soaked dressing.', 'PON 417 · Trauma & Orthopaedics'),
(2, 88, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient with a hip spica needs special care with:', '["Teeth only, as they cannot brush", "Hearing only", "Skin, elimination and breathing", "Vision only"]'::jsonb, 2, 'Protect the cast edges from soiling.', 'PON 417 · Trauma & Orthopaedics'),
(2, 89, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Fasciotomy wounds after compartment syndrome are:', '["Left untreated to heal on their own", "Covered with a full plaster cast to protect them", "Closed tightly at once with sutures", "Left open at first, then closed or grafted"]'::jsonb, 3, 'Monitor for infection and fluid loss.', 'PON 417 · Trauma & Orthopaedics'),
(2, 90, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The initial analgesic of choice for a patient with severe fracture pain (9/10) is:', '["Oral codeine", "IV paracetamol", "IV opiate", "Rectal NSAID"]'::jsonb, 2, 'Severe acute pain (9/10) needs a titrated IV opioid. Splinting and paracetamol are adjuncts.', 'PON 417 · Trauma & Orthopaedics'),
(2, 91, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A hard cervical collar must be correctly sized because a poorly fitting collar can:', '["Fail to immobilise the neck, or cause pressure sores", "Lower intracranial pressure in head injury", "Improve breathing by opening the airway and lowering ICP", "Cure the fracture without any other treatment"]'::jsonb, 0, 'Check skin under the collar regularly.', 'PON 417 · Trauma & Orthopaedics'),
(2, 92, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient with a skeletal traction pin has redness, pus and pain at the pin site. This indicates:', '["Normal skin reaction", "Loose weights", "Pin-site infection", "Normal healing"]'::jsonb, 2, 'Report, take a swab and give care as per protocol.', 'PON 417 · Trauma & Orthopaedics'),
(2, 93, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A 16 year-old is admitted to the floor after a foot-ball injury. The patient has a femur fracture. An external fixation device was applied in the operating room. The patient is at an increased risk for development of which of the following complications:', '["Pressure sore.", "Pulmonary embolism.", "Deep venous thrombosis.", "Post-traumatic stress disorder."]'::jsonb, 2, 'Immobilisation with external fixation and long bone fracture markedly raises DVT risk.', 'PON 417 · Trauma & Orthopaedics'),
(2, 94, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Arthroplasty means:', '["Amputation of a limb", "Fusion of the spine with rods and screws", "Removal of a bone tumour", "Surgical replacement or rebuilding of a joint"]'::jsonb, 3, 'Arthrodesis is joint fusion.', 'PON 417 · Trauma & Orthopaedics'),
(2, 95, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A supracondylar fracture of the humerus in a child puts which structure at particular risk?', '["The femoral artery", "The carotid artery", "The brachial artery", "The sciatic nerve in the thigh"]'::jsonb, 2, 'Check radial pulse, colour and capillary refill.', 'PON 417 · Trauma & Orthopaedics'),
(2, 96, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'After knee arthroscopy, the patient is advised to report:', '["A small dry dressing on the knee", "Tiredness from the anaesthetic on the first evening", "Increasing pain, swelling, fever or calf pain", "Mild stiffness on the first day"]'::jsonb, 2, 'These may mean infection or DVT.', 'PON 417 · Trauma & Orthopaedics'),
(2, 97, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A greenstick fracture is most common in:', '["Patients with bone tumours and cancer", "Athletes with stress injuries", "Children, because their bones are flexible", "Elderly adults with osteoporosis"]'::jsonb, 2, 'One side of the bone breaks while the other bends.', 'PON 417 · Trauma & Orthopaedics'),
(2, 98, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Before log rolling a patient with suspected spinal injury, the person controlling the head:', '["Gives the commands to the team", "Leaves the head unsupported", "Turns the head first", "Lets the team move on their own"]'::jsonb, 0, 'Usually at least four people are needed.', 'PON 417 · Trauma & Orthopaedics'),
(2, 99, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Carpal tunnel syndrome is compression of the:', '["Sciatic nerve in the buttock", "Radial nerve in the arm", "Ulnar nerve at the elbow", "Median nerve at the wrist"]'::jsonb, 3, 'Phalen''s and Tinel''s tests support the diagnosis.', 'PON 417 · Trauma & Orthopaedics'),
(2, 100, 'Perioperative Mock — Day 7 Afternoon (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'An abduction pillow after total hip replacement (posterior approach) is used to:', '["Elevate the heels off the bed to prevent pressure sores", "Keep the legs apart and prevent dislocation", "Cool the wound to reduce swelling", "Support the lower back in bed"]'::jsonb, 1, 'Avoid crossing the legs.', 'PON 417 · Trauma & Orthopaedics'),
(3, 1, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Magnesium sulfate is administered in severe preeclampsia primarily to:', '["Treat postpartum haemorrhage", "Lower blood glucose", "Prevent or treat eclamptic seizures", "Induce labour immediately"]'::jsonb, 2, 'Magnesium sulfate is the drug of choice for seizure prophylaxis and treatment in severe preeclampsia/eclampsia, requiring monitoring for signs of magnesium toxicity such as loss of deep tendon reflexes and respiratory depression.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 2, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A trial of labour after one previous lower segment caesarean section carries a small risk of:', '["Rh disease", "Uterine rupture", "Placenta praevia in that labour", "Hyperemesis"]'::jsonb, 1, 'Continuous fetal monitoring is advised.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 3, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Before major gynaecological surgery, blood is grouped and saved or cross-matched because:', '["It replaces the consent form", "It reduces infection", "The patient will always need a transfusion", "Pelvic surgery can cause heavy bleeding"]'::jsonb, 3, 'Check Hb and correct anaemia before elective surgery.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 4, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A septic abortion presents with:', '["Fever, offensive vaginal discharge, lower abdominal pain and shock", "Painless bleeding only", "High blood pressure only", "No symptoms, apart from a slightly late period"]'::jsonb, 0, 'Give IV antibiotics, fluids and evacuate the uterus.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 5, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Bartholin''s cyst recurrence is reduced by:', '["Simple needle aspiration only", "Antibiotic cream alone", "Ice packs", "Marsupialisation"]'::jsonb, 3, 'This creates a permanent opening for drainage.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 6, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Ovarian cystectomy differs from oophorectomy because it:', '["Removes both tubes", "Removes the whole ovary", "Removes the cyst and keeps the ovary", "Removes the uterus and both fallopian tubes"]'::jsonb, 2, 'It is preferred in young women to preserve fertility.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 7, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Post-menopausal bleeding should be investigated first to exclude:', '["Pregnancy", "Endometrial cancer", "Ovarian torsion", "Urinary tract infection"]'::jsonb, 1, 'Transvaginal ultrasound and endometrial biopsy are used.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 8, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A gravida 9 presents with history of amenorrhea for 7 weeks, PV bleeding, lower abdominal pain, and fainting twice yesterday. Her diagnosis is likely:', '["Implantation bleeding", "Placenta Previa", "Ectopic pregnancy", "Abortion"]'::jsonb, 2, 'Amenorrhoea, bleeding, abdominal pain, and fainting in a multigravida strongly suggest ectopic pregnancy.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 9, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Retained products after delivery causing secondary PPH often present:', '["Only during pregnancy, never after the birth of the baby", "Never after vaginal birth", "Days to weeks after birth with heavy bleeding and possible infection", "Within the first hour only"]'::jsonb, 2, 'Ultrasound and evacuation may be needed.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 10, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A third-degree perineal tear involves the:', '["Skin of the perineum only", "Vaginal mucosa only", "Rectal mucosa", "Anal sphincter complex"]'::jsonb, 3, 'A fourth-degree tear also involves the rectal mucosa.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 11, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Laparoscopic sterilisation commonly uses:', '["Filshie clips on the fallopian tubes", "An intrauterine device (IUD)", "Removal of the ovaries", "Hysterectomy"]'::jsonb, 0, 'It is permanent; a pregnancy test is done first.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 12, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A woman with a uterine scar (previous caesarean) and severe abdominal pain with fetal heart abnormalities in labour suggests:', '["Urinary tract infection", "Uterine rupture", "False labour", "Normal labour pain"]'::jsonb, 1, 'Immediate laparotomy is needed.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 13, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Following a vaginal birth with a postpartum haemorrhage of 1500 mL, the woman''s urine output should be:', '["Checked once the next day by weighing the pads", "Monitored hourly with a catheter", "Measured only by weighing pads", "Ignored if she feels well"]'::jsonb, 1, 'Low urine output signals ongoing hypovolaemia.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 14, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'For an instrumental delivery, the cervix must be:', '["Only 4 cm dilated", "Fully dilated with the head engaged", "Closed or only partly dilated", "Dilated with the head unengaged"]'::jsonb, 1, 'The bladder should also be emptied.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 15, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Primary postpartum haemorrhage following a caesarean section is defined as blood loss of:', '["≥3000ml", "≥250ml", "≥500ml", "≥1000ml"]'::jsonb, 3, 'The threshold is higher after a C-section (1000ml) compared to a vaginal delivery (500ml), reflecting the naturally greater blood loss expected with surgery.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 16, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Play therapy before surgery in children mainly helps to:', '["Speed up anaesthesia", "Reduce fear and help the child understand what will happen", "Replace the need for fasting before the operation", "Remove the need for consent"]'::jsonb, 1, 'Use age-appropriate explanations.', 'PON 423 · Paediatric Surgery'),
(3, 17, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'The maximum allowable blood loss calculation in children helps the team to:', '["Choose the instruments", "Know when to give blood during surgery", "Calculate the fasting time needed before surgery", "Decide the theatre temperature"]'::jsonb, 1, 'It is based on estimated blood volume and starting haematocrit.', 'PON 423 · Paediatric Surgery'),
(3, 18, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Pale stools and dark urine with prolonged jaundice in a 4-week-old baby suggest:', '["Biliary atresia (obstructive jaundice)", "Normal physiological jaundice", "Breast milk jaundice only", "Hypothyroidism only, needing thyroid hormone"]'::jsonb, 0, 'Urgent referral is needed.', 'PON 423 · Paediatric Surgery'),
(3, 19, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Tracheo-oesophageal fistula is often associated with which other congenital anomaly?', '["Club foot only", "Polydactyly only", "Cleft lip only", "Oesophageal atresia"]'::jsonb, 3, 'Tracheo-oesophageal fistula commonly co-occurs with oesophageal atresia, and the combination requires prompt surgical correction.', 'PON 423 · Paediatric Surgery'),
(3, 20, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'This condition describe a birth defect where some nerve cells are missing in the large intestine:', '["Pyloric Hirsh sprung", "Hirsh sprung disease", "Appendicitis", "Birth stenosis"]'::jsonb, 1, 'Absent nerve cells (ganglion cells) in the large intestine defines Hirschsprung''s disease.', 'PON 423 · Paediatric Surgery'),
(3, 21, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'In a child under 1 year, the head represents about what percentage of total body surface area in burns?', '["9%", "1%", "18%", "4.5%"]'::jsonb, 2, 'Children''s heads are larger, and legs smaller, than adults''.', 'PON 423 · Paediatric Surgery'),
(3, 22, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A baby with congenital diaphragmatic hernia typically has:', '["Bilious vomiting only", "A distended abdomen and normal breathing", "Respiratory distress and a scaphoid (sunken) abdomen", "Jaundice only, with a normal chest and breathing"]'::jsonb, 2, 'Bowel sounds may be heard in the chest.', 'PON 423 · Paediatric Surgery'),
(3, 23, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Unexplained fractures in an infant of different ages on X-ray should raise concern of:', '["Non-accidental injury (child abuse)", "Normal growth and development in infancy", "Simple falls only", "Vitamin C excess"]'::jsonb, 0, 'Follow safeguarding procedures.', 'PON 423 · Paediatric Surgery'),
(3, 24, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Immediately after birth, exposed bowel in gastroschisis should be:', '["Washed with antiseptic and pushed back gently into the abdomen at once", "Covered with dry gauze and pressed back", "Covered with cling film or a sterile bowel bag to reduce heat and fluid loss", "Left uncovered to air dry"]'::jsonb, 2, 'Keep the baby warm and place an NG tube.', 'PON 423 · Paediatric Surgery'),
(3, 25, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Inguinal hernias in premature babies are usually repaired:', '["Only after puberty", "Never; they always close on their own before school age", "Soon after diagnosis, because of the high risk of incarceration", "Only at 10 years of age"]'::jsonb, 2, 'Premature babies need post-operative apnoea monitoring.', 'PON 423 · Paediatric Surgery'),
(3, 26, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'A urostomy appliance (after ileal conduit) differs from a colostomy bag because it:', '["Has a tap/drainage outlet and anti-reflux valve for urine", "Has no outlet", "Collects faeces", "Is closed and changed each hour"]'::jsonb, 0, 'It is connected to a night drainage bag.', 'PON 423 · Urology'),
(3, 27, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'A suprapubic catheter is preferred over a urethral catheter when:', '["The bladder is empty", "Only a single urine sample is needed", "The patient is passing urine normally", "Long-term catheterisation is needed or the urethra is damaged"]'::jsonb, 3, 'Avoid in patients with bladder cancer or unknown bladder pathology.', 'PON 423 · Urology'),
(3, 28, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'After TURP, bright red urine with clots and falling blood pressure suggests:', '["Dehydration only", "Significant bleeding needing urgent review", "Urinary tract infection only", "Normal post-operative urine"]'::jsonb, 1, 'Increase irrigation, check the catheter and call the surgeon.', 'PON 423 · Urology'),
(3, 29, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'The best imaging test to confirm a suspected ureteric stone is:', '["Echocardiography", "Non-contrast CT of the kidneys, ureters and bladder", "Chest X-ray", "MRI of the brain"]'::jsonb, 1, 'Ultrasound is preferred in pregnancy and children.', 'PON 423 · Urology'),
(3, 30, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'Orchidopexy is performed to:', '["Drain fluid from the scrotum", "Repair a hernia only", "Bring an undescended testis into the scrotum and fix it", "Remove the testis"]'::jsonb, 2, 'It lowers the risk of infertility and allows examination for cancer.', 'PON 423 · Urology'),
(3, 31, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'Urodynamic studies are used to:', '["Assess bladder filling, storage and emptying function", "Test for stones", "Look at the kidneys on X-ray", "Measure kidney size"]'::jsonb, 0, 'They help plan incontinence treatment.', 'PON 423 · Urology'),
(3, 32, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'Epididymo-orchitis differs from testicular torsion because it:', '["Never causes pain", "Usually develops more gradually with fever and urinary symptoms", "Needs surgery within 6 hours", "Always comes on suddenly in young boys"]'::jsonb, 1, 'If in doubt, explore surgically for torsion.', 'PON 423 · Urology'),
(3, 33, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'Urethroplasty is surgery to:', '["Remove the kidney", "Fix the testis in the scrotum", "Remove the bladder", "Repair a urethral stricture"]'::jsonb, 3, 'Catheter care is important after surgery.', 'PON 423 · Urology'),
(3, 34, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'Prostate-specific antigen (PSA) is a blood test that may be raised in:', '["Kidney stones only", "Only prostate cancer", "Prostate cancer, BPH and prostatitis", "Bladder infections only"]'::jsonb, 2, 'Digital rectal examination and MRI help assessment.', 'PON 423 · Urology'),
(3, 35, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Urology', 'Priapism lasting more than 4 hours is:', '["A urological emergency, often linked to sickle cell disease", "A sign of good health", "Normal and needs no treatment", "Treated only with ice at home"]'::jsonb, 0, 'Treatment includes aspiration and drugs into the penis.', 'PON 423 · Urology'),
(3, 36, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient with a head injury has a Glasgow Coma Scale score of 10. This is classified as which severity of traumatic brain injury?', '["Vegetative state", "Moderate", "Mild", "Severe"]'::jsonb, 1, 'A GCS of 9-12 is classified as moderate traumatic brain injury, between mild (13-15) and severe (3-8).', 'PON 423 · Neurosurgery'),
(3, 37, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'Seizure precautions after craniotomy include:', '["Leaving the patient alone", "Padded side rails, suction at the bedside and anticonvulsants as prescribed", "Putting objects in the mouth during a seizure", "Restraining the patient tightly"]'::jsonb, 1, 'Time and document any seizure.', 'PON 423 · Neurosurgery'),
(3, 38, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'Cerebral Perfusion Pressure (CPP) is calculated as:', '["Mean Arterial Pressure minus Intracranial Pressure", "Heart Rate divided by Intracranial Pressure", "Diastolic Blood Pressure minus Heart Rate", "Systolic Blood Pressure plus Intracranial Pressure"]'::jsonb, 0, 'CPP = MAP − ICP; maintaining adequate CPP is a key goal in managing patients with raised intracranial pressure to ensure adequate cerebral blood flow.', 'PON 423 · Neurosurgery'),
(3, 39, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'Which nursing intervention can help prevent sharp spikes in ICP and surgical haemorrhage?', '["Give fluid restriction", "Help with breath exercises", "Administer an antiemetic to prevent vomiting", "Keep the head of the bed elevated"]'::jsonb, 3, 'Keeping the head of the bed elevated reduces ICP spikes and bleeding risk.', 'PON 423 · Neurosurgery'),
(3, 40, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'After a craniectomy, the patient should not lie on the side of the bone defect because:', '["It causes leg weakness", "There is no bone protecting the brain there", "It makes the patient deaf", "It increases wound infection"]'::jsonb, 1, 'A protective helmet may be worn when mobilising.', 'PON 423 · Neurosurgery'),
(3, 41, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'Monro-Kellie doctrine, or hypothesis, is that the sum of volume of brain, CSF, and intracranial blood is constant. An increase in one should cause a decrease in one or both of the remaining two leading to:', '["Normal heamodynamic", "Lower intracranial pressure", "Normal intracranial pressure", "Increase in the intracranial pressure"]'::jsonb, 3, 'By the Monro-Kellie doctrine, added volume in a fixed cranial space raises intracranial pressure.', 'PON 423 · Neurosurgery'),
(3, 42, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'A subdural hematoma most commonly results from tearing of which structure?', '["Anterior cerebral artery", "Bridging veins", "Basilar artery", "Middle meningeal artery"]'::jsonb, 1, 'Subdural hematomas arise from venous bleeding, typically from tearing of the bridging veins that traverse the subdural space between the brain surface and dura.', 'PON 423 · Neurosurgery'),
(3, 43, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'Positioning the head of bed at 30 degrees in a patient with raised intracranial pressure helps to:', '["Have no effect on cerebral perfusion", "Replace the need for other ICP-lowering measures", "Increase ICP further", "Promote venous drainage from the brain and help lower ICP"]'::jsonb, 3, 'Elevating the head of bed to about 30 degrees (with the head in neutral alignment) promotes venous outflow from the brain, helping to reduce intracranial pressure.', 'PON 423 · Neurosurgery'),
(3, 44, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient sustains a rotational acceleration-deceleration injury in a high-speed motor vehicle collision. The initial CT is normal, but the patient remains comatose for several days. Which type of head injury is most consistent with this presentation?', '["Diffuse axonal injury", "Epidural hematoma", "Depressed skull fracture", "Concussion"]'::jsonb, 0, 'Diffuse axonal injury results from shearing forces on axons during rapid rotational acceleration-deceleration; CT is often initially normal despite severe, prolonged unconsciousness.', 'PON 423 · Neurosurgery'),
(3, 45, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Neurosurgery', 'An awake craniotomy is performed mainly to:', '["Make surgery faster", "Map speech and motor areas during tumour removal", "Reduce anaesthetic costs", "Avoid any local anaesthetic"]'::jsonb, 1, 'The patient speaks or moves during parts of the operation.', 'PON 423 · Neurosurgery'),
(3, 46, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A patient on cardiopulmonary bypass is cooled mainly to:', '["Prevent bleeding", "Speed up recovery", "Increase heart rate", "Reduce oxygen demand of tissues"]'::jsonb, 3, 'Rewarming is done slowly before coming off bypass.', 'PON 423 · Cardiothoracic Surgery'),
(3, 47, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A thoracic epidural after thoracotomy should be monitored for:', '["Only skin colour", "Only the patient''s appetite", "Block height, blood pressure and respiratory function", "Only hearing"]'::jsonb, 2, 'Hypotension and motor block can occur.', 'PON 423 · Cardiothoracic Surgery'),
(3, 48, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Chest drain tubing should be:', '["Kept free of loops hanging below the bottle and free of kinks", "Taped to the floor", "Clamped routinely", "Looped below the bottle"]'::jsonb, 0, 'Dependent loops can block drainage.', 'PON 423 · Cardiothoracic Surgery'),
(3, 49, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A nurse is caring for a patient with a chest tube connected to UWSD. The nurse notices the drainage has stopped. What is the most appropriate initial nursing action?', '["Increase the suction to the system", "Clamp the chest tube and call the physician", "Remove the chest tube", "Check for kinks in the tubing and reposition the patient"]'::jsonb, 3, 'A sudden cessation of drainage may be caused by a kinked tube or the patient''s position obstructing the flow. The nurse should first troubleshoot the system by checking for kinks and repositioning the patient before escalating the issue to the physician. Removing the tube would be an unsafe action.', 'PON 423 · Cardiothoracic Surgery'),
(3, 50, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Haemorrhage after thoracotomy can be classified as:', '["Only ever primary", "Primary, reactionary, or secondary", "A trivial, non-life-threatening complication", "Unrelated to the type of surgery performed"]'::jsonb, 1, 'Recognising which type of bleeding is occurring (immediate, early post-op, or delayed/infection-related) helps guide the appropriate management.', 'PON 423 · Cardiothoracic Surgery'),
(3, 51, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Continuous bubbling in the water seal chamber of a chest drainage system suggests:', '["The chest tube has been successfully removed", "An air leak in the system or from the pleural space", "Overdrainage of pleural fluid", "Normal, expected fluctuation with respiration"]'::jsonb, 1, 'Continuous (rather than intermittent, respiration-related) bubbling in the water seal chamber suggests an air leak, either from the pleural space (persistent pneumothorax) or a loose connection in the drainage system.', 'PON 423 · Cardiothoracic Surgery'),
(3, 52, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Infective endocarditis prophylaxis before dental procedures is considered for patients with:', '["Diabetes only", "Normal hearts", "Hypertension only", "Prosthetic heart valves"]'::jsonb, 3, 'Good dental hygiene is important for all heart valve patients.', 'PON 423 · Cardiothoracic Surgery'),
(3, 53, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A patient with a chest drain has a sudden large increase in bloody drainage with falling BP. The nurse should:', '["Call for urgent help, monitor and prepare for transfusion", "Raise the drain above the chest", "Clamp the drain and leave it", "Remove the drain"]'::jsonb, 0, 'Ongoing bleeding may need surgery.', 'PON 423 · Cardiothoracic Surgery'),
(3, 54, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A clicking, unstable sternum with wound discharge after cardiac surgery suggests:', '["Muscle strain", "Pneumonia only", "Sternal dehiscence or deep sternal wound infection", "Normal healing"]'::jsonb, 2, 'Report urgently.', 'PON 423 · Cardiothoracic Surgery'),
(3, 55, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A nurse finds the UWSD system on the floor, and the water-seal is broken. The most appropriate initial action is to:', '["Submerge the chest tube''s end in a bottle of sterile water", "Clamp the chest tube and call the physician", "Immediately replace the UWSD system", "Cover the chest tube with a sterile dressing"]'::jsonb, 0, 'If the water seal is broken, the chest tube should immediately be placed in a container of sterile water to re-establish the water seal and prevent air from entering the chest cavity. The system should then be replaced as soon as possible.', 'PON 423 · Cardiothoracic Surgery'),
(3, 56, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'How many points are there in Braden scale basic assessment tool to determine a patient risk for pressure ulcers', '["4", "8", "5", "6"]'::jsonb, 3, 'The Braden scale pressure-ulcer risk assessment tool has 6 subscales/points.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 57, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A pressure ulcer with exposed bone or tendon is:', '["Category/stage 1", "Category/stage 3 only", "Category/stage 4", "Category/stage 2"]'::jsonb, 2, 'It may need surgical debridement and flap closure.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 58, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A patient has total burns to the groin, anterior trunk and the the left upper limb. Using the Wallace rules of nine, the TBSAB is?', '["29%", "36%", "27%", "28%"]'::jsonb, 1, 'Groin (1%) + anterior trunk (18%) + left upper limb (9%) = 28%, closest matching answer is A given typical Wallace rule combinations (approximated to 36% if groin counted differently) — select based on standard summation closest to provided options.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 59, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The leading cause of death in burns patients after 48 hours is:', '["Electrolyte imbalance", "Sepsis", "Hypovolaemic shock", "Airway obstruction"]'::jsonb, 1, 'The open burn wound becomes an entry point for bacteria once the acute fluid-shift phase has passed.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 60, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A cleft lip repair site is protected after surgery by:', '["Leaving it dirty", "Rubbing it firmly with gauze", "Keeping it clean and preventing the child from rubbing it", "Applying ice packs for days"]'::jsonb, 2, 'Arm splints may be used.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 61, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Burns contractures across joints are best prevented by:', '["Tight bandages", "Keeping the joint flexed all the time", "Splinting, positioning and early physiotherapy", "Avoiding all movement"]'::jsonb, 2, 'Position the joint in an anti-contracture position.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 62, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A burn injury is best defined as:', '["Coagulative necrosis", "Fat necrosis", "Caseous necrosis", "Liquefactive necrosis"]'::jsonb, 0, 'Heat denatures/cooks tissue proteins — this specific process is coagulative necrosis.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 63, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A burns patient''s diet should be:', '["Low in protein", "Water only", "Very low in calories", "High in protein and calories"]'::jsonb, 3, 'Burns greatly increase metabolic demands.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 64, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A pressure ulcer with intact skin and non-blanching redness is classified as:', '["Category/stage 1", "Category/stage 2", "Category/stage 4", "Category/stage 3"]'::jsonb, 0, 'Stage 2 is partial-thickness skin loss; stage 4 exposes bone or tendon.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 65, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A burns patient''s wound care plan includes silver sulfadiazine cream. The nurse understands this agent is used primarily for its:', '["Analgesic properties only", "Broad-spectrum antimicrobial effect, helping prevent burn wound infection", "Cooling effect only", "Ability to promote scar-free healing with no infection benefit"]'::jsonb, 1, 'Silver sulfadiazine is a topical antimicrobial agent commonly used in burn wound care to reduce the risk of infection.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(3, 66, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A dentoalveolar fracture involves:', '["The femur", "The spine", "The whole skull", "The teeth and the supporting alveolar bone"]'::jsonb, 3, 'It is common in falls and sports injuries.', 'PON 417 · Maxillofacial Surgery'),
(3, 67, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A blow-out fracture of the orbital floor may cause:', '["Hand numbness", "Hearing loss", "Loss of taste only", "Double vision on upward gaze and a sunken eye"]'::jsonb, 3, 'Inferior rectus entrapment limits upward gaze.', 'PON 417 · Maxillofacial Surgery'),
(3, 68, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A dental abscess causing swelling of the floor of the mouth and raised tongue is dangerous because:', '["It always resolves alone", "It can obstruct the airway (Ludwig''s angina)", "It causes hearing loss", "It improves swallowing"]'::jsonb, 1, 'Secure the airway and drain the infection urgently.', 'PON 417 · Maxillofacial Surgery'),
(3, 69, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A submandibular gland stone typically causes:', '["Pain and swelling under the jaw when eating", "Leg pain", "Hearing loss", "Double vision"]'::jsonb, 0, 'Saliva flow is blocked by the stone.', 'PON 417 · Maxillofacial Surgery'),
(3, 70, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Nasal intubation is often used in maxillofacial surgery to:', '["Avoid the need for anaesthesia", "Reduce bleeding from the nose", "Keep the mouth free and allow teeth to be brought together", "Make extubation impossible"]'::jsonb, 2, 'It is avoided in suspected skull base fractures.', 'PON 417 · Maxillofacial Surgery'),
(3, 71, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Temporomandibular joint (TMJ) dislocation presents with:', '["Double vision", "Loss of hearing", "Inability to open the mouth at all", "Inability to close the mouth"]'::jsonb, 3, 'Reduction is done by pushing the mandible down and back.', 'PON 417 · Maxillofacial Surgery'),
(3, 72, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Facial nerve palsy after parotid surgery is tested by asking the patient to:', '["Close the eyes tightly, smile and raise the eyebrows", "Stick out the tongue only", "Shrug the shoulders", "Follow a finger with the eyes only"]'::jsonb, 0, 'Protect the eye if eyelid closure is weak.', 'PON 417 · Maxillofacial Surgery'),
(3, 73, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A neck dissection is performed for:', '["Thyroid storm", "Removal of lymph nodes in head and neck cancer", "A broken jaw", "Dental caries"]'::jsonb, 1, 'Watch for haematoma, shoulder weakness and chyle leak.', 'PON 417 · Maxillofacial Surgery'),
(3, 74, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'After oral cancer surgery with a flap, the nurse should check the flap and:', '["Avoid oral care", "Feed the patient solid food immediately", "Maintain a clear airway, often via tracheostomy", "Allow smoking to reduce stress"]'::jsonb, 2, 'Oral hygiene protects the surgical site.', 'PON 417 · Maxillofacial Surgery'),
(3, 75, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A patient with jaw wiring is nourished mainly with:', '["Normal solid food", "Only plain water", "Nothing by mouth for 6 weeks", "A liquid or blended high-calorie diet"]'::jsonb, 3, 'Dietitian advice helps maintain weight.', 'PON 417 · Maxillofacial Surgery'),
(3, 76, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Entropion is a condition in which:', '["The eyelid turns outward", "The eye bulges forward", "The eyelid turns inward and lashes rub the cornea", "The pupil is fixed"]'::jsonb, 2, 'Trachoma scarring causes entropion and trichiasis.', 'PON 417 · Ophthalmic Surgery'),
(3, 77, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Thyroid eye disease (Graves'' ophthalmopathy) may cause:', '["Night blindness only", "Cataract only", "Small sunken eyes", "Bulging eyes (proptosis) and lid retraction"]'::jsonb, 3, 'Protect the cornea; severe cases need steroids or surgery.', 'PON 417 · Ophthalmic Surgery'),
(3, 78, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'After vitrectomy with a gas bubble, the patient must not:', '["Walk", "Sleep", "Fly or travel to high altitude until the gas is absorbed", "Eat food"]'::jsonb, 2, 'Gas expands at altitude and can raise eye pressure dangerously.', 'PON 417 · Ophthalmic Surgery'),
(3, 79, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Before cataract surgery, biometry is performed to:', '["Calculate the power of the lens implant", "Measure blood sugar", "Measure blood pressure", "Check hearing"]'::jsonb, 0, 'Accurate measurement gives the right post-operative vision.', 'PON 417 · Ophthalmic Surgery'),
(3, 80, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A stye (hordeolum) is:', '["A type of cataract", "A painless eyelid cyst", "An acute painful infection of an eyelash follicle", "A squint"]'::jsonb, 2, 'Warm compresses help it drain.', 'PON 417 · Ophthalmic Surgery'),
(3, 81, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Vitrectomy is removal of the:', '["Vitreous gel from the eye", "Cornea", "Eyelid", "Lens"]'::jsonb, 0, 'It is used for retinal detachment and vitreous haemorrhage.', 'PON 417 · Ophthalmic Surgery'),
(3, 82, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'After squint surgery, the patient may have:', '["Total blindness", "Severe bleeding as normal", "Loss of hearing", "A red eye and mild discomfort for a few days"]'::jsonb, 3, 'Antibiotic drops are often given.', 'PON 417 · Ophthalmic Surgery'),
(3, 83, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'When instilling two different eye drops, the patient should wait about:', '["5 seconds between drops", "No time at all", "2 hours between drops", "5 minutes between drops"]'::jsonb, 3, 'This stops the first drop being washed out.', 'PON 417 · Ophthalmic Surgery'),
(3, 84, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Hyphaema is:', '["Pus behind the cornea", "Swelling of the optic disc", "Blood in the anterior chamber of the eye", "Inflammation of the eyelid"]'::jsonb, 2, 'Rest, head elevation and eye pressure monitoring are needed.', 'PON 417 · Ophthalmic Surgery'),
(3, 85, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'After eye surgery, the patient is told to avoid:', '["Heavy lifting, bending and rubbing the eye", "Walking", "Reading slowly", "Eating normally"]'::jsonb, 0, 'These actions may raise eye pressure.', 'PON 417 · Ophthalmic Surgery'),
(3, 86, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Oesophagoscopy for a foreign body (e.g. fish bone) carries a risk of:', '["Oesophageal perforation", "Kidney stones", "Eye injury", "Hearing loss"]'::jsonb, 0, 'Fever, chest pain and neck swelling after the procedure must be reported.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 87, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Quinsy is treated by:', '["Drainage of the abscess and IV antibiotics", "Eye drops", "Nasal packing", "Ear drops"]'::jsonb, 0, 'Trismus and a deviated uvula are common signs.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 88, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'After middle ear surgery, a patient develops facial weakness. This suggests:', '["Infection of the knee", "Hearing improvement", "Normal recovery", "Facial nerve injury or swelling"]'::jsonb, 3, 'Report immediately to the surgeon.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 89, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Mastoidectomy is performed for:', '["Tonsillitis", "Nasal fracture", "Chronic infection or cholesteatoma in the mastoid bone", "Thyroid cancer"]'::jsonb, 2, 'Watch for facial nerve weakness and dizziness after surgery.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 90, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Rinne''s test is positive (normal) when:', '["Sound lateralises to one ear", "Bone conduction is better than air conduction", "Air conduction is better than bone conduction", "No sound is heard"]'::jsonb, 2, 'A negative Rinne suggests conductive loss.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 91, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A tracheostomy cuff is deflated when using a speaking valve because:', '["Air must pass around the tube up through the vocal cords", "It helps swallowing only", "The valve blocks all breathing", "It prevents infection"]'::jsonb, 0, 'Never use a speaking valve with an inflated cuff.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 92, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Ear syringing (irrigation) is contraindicated in a patient with:', '["A perforated eardrum", "A cold", "Normal hearing", "Hard wax"]'::jsonb, 0, 'Water can enter the middle ear and cause infection.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 93, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A branchial cyst is:', '["A congenital cyst in the side of the neck", "A thyroid cancer", "An ear infection", "A type of nasal polyp"]'::jsonb, 0, 'It is usually found in young adults.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 94, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Septoplasty is surgery to:', '["Remove a vocal cord nodule", "Remove the tonsils", "Repair the eardrum", "Straighten a deviated nasal septum"]'::jsonb, 3, 'It improves nasal breathing.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 95, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A tracheo-oesophageal voice prosthesis after laryngectomy allows:', '["Speech by directing air into the oesophagus", "Breathing through the nose", "Hearing through the stoma", "Feeding through the trachea"]'::jsonb, 0, 'Teach the patient to clean and care for the valve.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 96, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A child with a nasal foreign body typically presents with:', '["Eye redness only", "Hearing loss", "Bilateral clear discharge", "One-sided, foul-smelling nasal discharge"]'::jsonb, 3, 'Remove it carefully with the right instruments.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 97, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A cholesteatoma left untreated can cause:', '["Nasal polyps only", "Tooth decay", "Erosion of bone with facial palsy and brain abscess", "Better hearing"]'::jsonb, 2, 'Surgery is the main treatment.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 98, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Conductive hearing loss is caused by:', '["Damage to the auditory nerve", "Problems in the outer or middle ear, e.g. wax or glue ear", "Damage to the cochlea", "Brain stroke only"]'::jsonb, 1, 'Sensorineural loss involves the inner ear or nerve.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 99, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A preauricular sinus is:', '["A nasal polyp", "A small congenital pit in front of the ear", "A fracture of the jaw", "A tonsil abscess"]'::jsonb, 1, 'Recurrent infection may need surgical excision.', 'PON 415 · Otorhinolaryngology (ENT)'),
(3, 100, 'Perioperative Mock — Day 7 Night (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Ototoxic drugs that can cause hearing loss include:', '["Paracetamol", "Vitamin C", "Gentamicin and high-dose furosemide", "Iron tablets"]'::jsonb, 2, 'Monitor drug levels and hearing.', 'PON 415 · Otorhinolaryngology (ENT)');
